def hill_climb(start: list) -> tuple:
    """Move to the best neighbor until none helps."""
    cur, cur_cost = start[:], cost(start)
    while True:
        best, best_c = None, cur_cost
        for nb in neighbors(cur):
            if cost(nb) < best_c:
                best, best_c = nb, cost(nb)
        if best is None:
            break
        cur, cur_cost = best, best_c
    return cur, cur_cost

def hill_climb_restarts(seed: int,
                        n_restarts: int) -> tuple:
    """Best local optimum over n_restarts climbs."""
    rng = random.Random(seed)
    best_perm, best_cost = None, float('inf')
    for _ in range(n_restarts):
        start = list(range(6))
        rng.shuffle(start)
        end, end_cost = hill_climb(start)
        if end_cost < best_cost:
            best_perm, best_cost = end, end_cost
    return best_perm, best_cost

